// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title DocumentVault
 * @notice Secure document upload and verification system
 * @dev Uses signature-based authentication for document submissions
 */
contract DocumentVault is Ownable {
    using ECDSA for bytes32;

    struct Document {
        bytes32 contentHash;
        address uploader;
        uint256 timestamp;
        bool verified;
    }

    mapping(bytes32 => Document) public documents;
    mapping(address => bool) public authorizedUploaders;
    mapping(bytes32 => bool) public usedNonces;

    // Authentication state for multi-step upload
    mapping(address => bytes32) private _pendingAuthHash;
    mapping(address => uint256) private _authTimestamp;

    uint256 public constant AUTH_WINDOW = 300; // 5 minutes

    event DocumentUploaded(bytes32 indexed docId, address indexed uploader);
    event UploaderAuthorized(address indexed uploader);
    event AuthInitiated(address indexed user);

    constructor() Ownable() {
        authorizedUploaders[msg.sender] = true;
    }

    function authorizeUploader(address uploader) external onlyOwner {
        authorizedUploaders[uploader] = true;
        emit UploaderAuthorized(uploader);
    }

    /**
     * @notice Step 1: Initiate authentication by providing credentials hash
     * @param credentialHash The keccak256 of user's authentication credentials
     */
    function initiateAuth(bytes32 credentialHash) external {
        require(authorizedUploaders[msg.sender], "Not authorized");
        _pendingAuthHash[msg.sender] = credentialHash;
        _authTimestamp[msg.sender] = block.timestamp;
        emit AuthInitiated(msg.sender);
    }

    /**
     * @notice Step 2: Complete authentication and upload document
     * @param documentContent The raw document bytes
     * @param nonce Unique nonce to prevent replay
     * @param signature ECDSA signature over the auth payload
     */
    function authenticatedUpload(
        bytes calldata documentContent,
        bytes32 nonce,
        bytes memory signature
    ) external {
        require(authorizedUploaders[msg.sender], "Not authorized");
        require(!usedNonces[nonce], "Nonce already used");
        require(_authTimestamp[msg.sender] + AUTH_WINDOW >= block.timestamp, "Auth expired");

        bytes32 pendingHash = _pendingAuthHash[msg.sender];
        require(pendingHash != bytes32(0), "No pending auth");

        // Verify the signature matches the pending auth
        bytes32 authPayload = _computeAuthPayload(pendingHash, nonce, msg.sender);
        address signer = _recoverSigner(authPayload, signature);

        require(_validateAuth(signer, msg.sender, pendingHash), "Auth validation failed");

        usedNonces[nonce] = true;

        bytes32 docId = keccak256(abi.encodePacked(documentContent, msg.sender, block.timestamp));
        documents[docId] = Document({
            contentHash: keccak256(documentContent),
            uploader: msg.sender,
            timestamp: block.timestamp,
            verified: true
        });

        // Clear auth state
        _pendingAuthHash[msg.sender] = bytes32(0);
        _authTimestamp[msg.sender] = 0;

        emit DocumentUploaded(docId, msg.sender);
    }

    /**
     * @dev Computes the authentication payload for signature verification
     */
    function _computeAuthPayload(
        bytes32 credentialHash,
        bytes32 nonce,
        address user
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(credentialHash, nonce, user));
    }

    /**
     * @dev Recovers signer from signature
     */
    function _recoverSigner(
        bytes32 payload,
        bytes memory signature
    ) internal pure returns (address) {
        // Note: we pass the raw hash for recovery
        return payload.recover(signature);
    }

    /**
     * @dev Validates authentication by comparing the recovered signer's
     *      credential hash against the pending hash. This allows delegated
     *      signing where the signer proves knowledge of credentials.
     */
    function _validateAuth(
        address signer,
        address caller,
        bytes32 pendingHash
    ) internal pure returns (bool) {
        // The authentication is valid if the hash of the signer address
        // matches the pending credential hash, OR if signer equals caller
        // (self-authenticated upload)
        bytes32 signerCredential = keccak256(abi.encodePacked(signer));
        return signerCredential == pendingHash || signer == caller;
    }

    /**
     * @notice Verify a document's authenticity
     */
    function verifyDocument(bytes32 docId) external view returns (bool) {
        return documents[docId].verified && documents[docId].contentHash != bytes32(0);
    }

    /**
     * @notice Get the credential hash for an address (used in auth setup)
     */
    function getCredentialHash(address user) external pure returns (bytes32) {
        return keccak256(abi.encodePacked(user));
    }
}
